"""ESPHome Light: OpenBridge adapter (generated by `openbridge partner new`, transport filled in).

Talks to an ESPHome node over its local `web_server` REST API (enable `web_server:` in the device YAML;
no cloud, no account). One light (on/off, brightness, toggle) plus, when configured, one switch
(on/off, toggle), cover commands (open/close/stop) with position read-back, climate temperature
reads and named sensor reads. Cover/climate actions beyond the cover buttons stay read-only until
their action URLs are verified on hardware. OTA updates, restarts and configuration are refused
by policy.

Every write is typed and allowlisted, read back from the device, and undoable exactly when it is reversible.

Status: emulator only. Record real-hardware runs in docs/DEVICE_EVIDENCE.json before claiming support.
The REST shapes below follow the documented web_server API; parsing stays tolerant (ON/on/true,
brightness 0-255 or 0-100) and anything unrecognized fails closed with EsphomeLightError, never as a
fake success.
"""
import base64
import json
import urllib.error
import urllib.request

READ = {'power': '', 'brightness': '%', 'firmware': '', 'switch': '', 'cover': '%',
        'climate_temp': '', 'climate_target': ''}
WRITABLE = {'power': ('on', 'off'), 'brightness': tuple(range(0, 101)), 'switch': ('on', 'off')}
COMMANDS = {'toggle': None, 'switch_toggle': None, 'cover_open': None, 'cover_close': None, 'cover_stop': None}
POLICY = {('firmware', '*'): 'Firmware is never changed by OpenBridge.',
          ('ota', '*'): 'OTA updates are never triggered by OpenBridge.',
          ('restart', '*'): 'OpenBridge never restarts the device.',
          ('configuration', '*'): 'Device configuration is never changed by OpenBridge.'}

TIMEOUT_S = 5
MAX_BODY = 65536


class EsphomeLightBlocked(PermissionError):
    """Refused before anything was sent."""


class EsphomeLightError(OSError):
    """The device could not be reached or answered something unrecognized."""


def _host_allowed(host):
    from src.fabric import netguard
    return netguard.local_host(host, bare_names=True, extra_names=('esphome',))


def _parse_power(doc):
    state = doc.get('state')
    if isinstance(state, bool):
        return 'on' if state else 'off'
    s = str(state or '').strip().lower()
    if s in ('on', 'true', '1'):
        return 'on'
    if s in ('off', 'false', '0'):
        return 'off'
    raise EsphomeLightError('unrecognized light state %r' % (state,))


def _parse_brightness(doc):
    for key in ('brightness', 'brightness_pct', 'level'):
        if key in doc and doc[key] is not None:
            try:
                v = float(doc[key])
            except (TypeError, ValueError):
                continue
            if key in ('brightness_pct', 'level') or v <= 100 and doc.get('brightness_scale') == 100:
                return max(0, min(100, int(round(v))))
            if 0 <= v <= 255:                       # ESPHome reports 0-255; OpenBridge shows 0-100
                return max(0, min(100, int(round(v * 100 / 255))))
    raise EsphomeLightError('no brightness in %r' % (sorted(doc),))


def _check_id(kind, eid):
    if not eid or not str(eid).replace('_', '').replace('-', '').isalnum():
        raise EsphomeLightBlocked('bad %s id %r' % (kind, eid))
    return str(eid)


class EsphomeLightTransport:
    """HTTP client for the ESPHome web_server API. Three methods: read, write, command.

    light_id is required (this adapter's first-class entity); switch_id, cover_id, climate_id and
    sensors ({fact name: entity id}) are optional extras, each read best-effort so one missing
    entity never hides the light."""

    def __init__(self, host, light_id, port=80, username=None, password=None, timeout=TIMEOUT_S,
                 switch_id=None, cover_id=None, climate_id=None, sensors=None):
        if not _host_allowed(host):
            raise EsphomeLightBlocked('refusing non-local ESPHome host %r' % (host,))
        self.base = 'http://%s:%d' % (host.strip(), int(port))
        self.light_id = _check_id('light', light_id)
        self.switch_id = _check_id('switch', switch_id) if switch_id is not None else None
        self.cover_id = _check_id('cover', cover_id) if cover_id is not None else None
        self.climate_id = _check_id('climate', climate_id) if climate_id is not None else None
        self.sensors = {}
        for fact, eid in dict(sensors or {}).items():
            if not isinstance(fact, str) or not fact.replace('_', '').isalnum() or len(fact) > 32:
                raise EsphomeLightBlocked('bad sensor fact name %r' % (fact,))
            self.sensors[fact] = _check_id('sensor', eid)
        self.timeout = timeout
        self.auth = None
        if username is not None or password is not None:
            raw = ('%s:%s' % (username or '', password or '')).encode()
            self.auth = 'Basic ' + base64.b64encode(raw).decode('ascii')

    def _request(self, method, path, body=None):
        if path != '/device-info' and (not path.startswith('/') or path.split('/')[1] not in
                                       ('light', 'switch', 'cover', 'climate', 'sensor')):
            raise EsphomeLightBlocked('refusing unexpected ESPHome path %r' % (path,))
        data = None
        headers = {}
        if body is not None:
            data = json.dumps(body).encode()
            headers['Content-Type'] = 'application/json'
        if self.auth:
            headers['Authorization'] = self.auth
        req = urllib.request.Request(self.base + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                raw = resp.read(MAX_BODY + 1)
        except (OSError, ValueError) as e:
            raise EsphomeLightError('%s %s failed: %s' % (method, path, e)) from None
        if len(raw) > MAX_BODY:
            raise EsphomeLightError('%s %s answered too much' % (method, path))
        if resp.status >= 400:
            raise EsphomeLightError('%s %s: HTTP %s' % (method, path, resp.status))
        try:
            return json.loads(raw.decode('utf-8')) if raw.strip() else {}
        except ValueError:
            raise EsphomeLightError('%s %s: not JSON' % (method, path)) from None

    def _entity_path(self, kind, eid, *parts):
        allowed = {'light': ('turn_on', 'turn_off', 'toggle'), 'switch': ('turn_on', 'turn_off', 'toggle'),
                   'cover': ('open', 'close', 'stop')}
        for p in parts:
            if p not in allowed.get(kind, ()):
                raise EsphomeLightBlocked('refusing unexpected ESPHome action %r' % (p,))
        return '/%s/%s%s' % (kind, eid, ''.join('/' + p for p in parts))

    def _optional(self, kind, eid):
        try:
            doc = self._request('GET', '/%s/%s' % (kind, eid))
        except EsphomeLightError:
            return None
        return doc if isinstance(doc, dict) else None

    def read(self):
        doc = self._request('GET', '/light/%s' % self.light_id)
        if not isinstance(doc, dict):
            raise EsphomeLightError('light state is not an object')
        state = {'power': _parse_power(doc), 'brightness': _parse_brightness(doc)}
        try:
            info = self._request('GET', '/device-info')
        except EsphomeLightError:
            info = {}
        if isinstance(info, dict):
            for key in ('esphome_version', 'version', 'firmware'):
                if info.get(key):
                    state['firmware'] = str(info[key])[:32]
                    break
        if self.switch_id is not None:
            s = self._optional('switch', self.switch_id)
            if s is not None:
                try:
                    state['switch'] = _parse_power(s)
                except EsphomeLightError:
                    pass
        if self.cover_id is not None:
            c = self._optional('cover', self.cover_id)
            if c is not None:
                pos = c.get('position', c.get('current_position'))
                try:
                    state['cover'] = max(0, min(100, int(round(float(pos)))))
                except (TypeError, ValueError):
                    if isinstance(c.get('state'), str):
                        st = c['state'].strip().lower()
                        if st in ('open', 'opening'):
                            state['cover'] = 100
                        elif st in ('closed', 'closing'):
                            state['cover'] = 0
        if self.climate_id is not None:
            c = self._optional('climate', self.climate_id)
            if c is not None:
                for fact, keys in (('climate_temp', ('current_temperature', 'temperature')),
                                   ('climate_target', ('target_temperature',))):
                    for k in keys:
                        try:
                            state[fact] = round(float(c[k]), 1)
                        except (KeyError, TypeError, ValueError):
                            continue
                        break
        for fact, eid in self.sensors.items():
            s = self._optional('sensor', eid)
            if s is None:
                continue
            for k in ('value', 'state'):
                try:
                    state[fact] = round(float(s[k]), 2)
                except (KeyError, TypeError, ValueError):
                    continue
                break
        return state

    def write(self, name, value):
        if name == 'power':
            self._request('POST', self._entity_path('light', self.light_id, 'turn_on' if value == 'on' else 'turn_off'))
        elif name == 'brightness':
            self._request('POST', self._entity_path('light', self.light_id, 'turn_on'),
                          {'brightness': max(0, min(255, int(round(value * 255 / 100))))})
        elif name == 'switch':
            if self.switch_id is None:
                raise EsphomeLightBlocked('no switch configured on this ESPHome node')
            self._request('POST', self._entity_path('switch', self.switch_id, 'turn_on' if value == 'on' else 'turn_off'))
        else:
            raise EsphomeLightBlocked('%s is not writable on an ESPHome node' % (name,))

    def command(self, name, value=None):
        if value is not None:
            raise EsphomeLightBlocked('%s takes no value' % (name,))
        if name == 'toggle':
            self._request('POST', self._entity_path('light', self.light_id, 'toggle'))
        elif name == 'switch_toggle':
            if self.switch_id is None:
                raise EsphomeLightBlocked('no switch configured on this ESPHome node')
            self._request('POST', self._entity_path('switch', self.switch_id, 'toggle'))
        elif name in ('cover_open', 'cover_close', 'cover_stop'):
            if self.cover_id is None:
                raise EsphomeLightBlocked('no cover configured on this ESPHome node')
            self._request('POST', self._entity_path('cover', self.cover_id,
                                                    {'cover_open': 'open', 'cover_close': 'close',
                                                     'cover_stop': 'stop'}[name]))
        else:
            raise EsphomeLightBlocked('%s is not an ESPHome command' % (name,))


def _refusal(name, value):
    return POLICY.get((name, value)) or POLICY.get((name, '*'))


class EsphomeLight:
    def __init__(self, transport):
        self.transport = transport
        self._before = {}

    def facts(self):
        state = self.transport.read()
        out = [{'name': k, 'value': state[k], 'unit': unit} for k, unit in READ.items() if k in state]
        out += [{'name': k, 'value': state[k], 'unit': ''}      # configured sensor facts
                for k in sorted(state) if k not in READ]
        return out

    def set_reversible(self, name, value):
        reason = _refusal(name, value)
        if reason:
            raise EsphomeLightBlocked(reason)
        if name not in WRITABLE or value not in WRITABLE[name]:
            raise EsphomeLightBlocked('%s=%r is not an allowed setting' % (name, value))
        if name in self._before:
            raise EsphomeLightBlocked('this setting has a pending Undo; undo it before changing it again')
        before = self.transport.read()
        if name not in before:
            raise EsphomeLightBlocked('the device does not report %s' % name)
        self.transport.write(name, value)
        after = self.transport.read().get(name)
        verified = after == value
        if verified:
            self._before[name] = before[name]
        return {'setting': name, 'before': before[name], 'after': after, 'verified': verified, 'reversible': True}

    def undo(self, name):
        if name not in self._before:
            raise EsphomeLightBlocked('nothing to undo for %s' % name)
        target = self._before[name]
        self.transport.write(name, target)
        now = self.transport.read().get(name)
        if now == target:
            self._before.pop(name)
        return {'setting': name, 'restored': now, 'exact': now == target}

    def command(self, name, value=None):
        reason = _refusal(name, value)
        if reason:
            raise EsphomeLightBlocked(reason)
        if name not in COMMANDS or (COMMANDS[name] is None and value is not None) or (COMMANDS[name] is not None and value not in COMMANDS[name]):
            raise EsphomeLightBlocked('%s is not an allowed command' % name)
        self.transport.command(name, value)
        # Momentary commands leave no lasting state to read back: reported as executed, never as verified.
        return {'command': name, 'value': value, 'verified': None, 'reversible': False}
